"use client"

import { EditViewer } from "@/components/viewers/edit/edit-viewer"
import type { FormField } from "@/components/viewers/lib/edit-types"
import editSample from "@/components/viewers/sample-data/edit.json"

const ORIGINAL_PDF_URL = "/samples/fidelity-edit/fidelity_original.pdf"

// A template-fill of the Fidelity "Bank Wire Authorization" form: 29 detected
// form fields across 3 pages, each with a normalized bbox and an inferred value.
const EDIT_FIELDS = editSample as FormField[]

/**
 * Edit viewer block — detected fields beside the source document, linked by
 * their bbox. `EditViewer` owns edit-specific modes, field visuals, search,
 * filters, and page grouping while segmented-document owns hover,
 * selection, and scroll-to-field behavior.
 */
export function EditViewerBlock() {
  return (
    <div className="flex h-full min-h-[680px] flex-col bg-background">
      <EditViewer
        result={{ fields: EDIT_FIELDS }}
        sourceDocument={{
          src: ORIGINAL_PDF_URL,
          mimeType: "application/pdf",
          filename: "fidelity-bank-wire-authorization.pdf",
        }}
      />
    </div>
  )
}

import type { DocumentAnchor } from "@/components/ui/document-anchor"
import type { BBox } from "@/components/viewers/lib/edit-types"

export type EditViewerMode = "source" | "preview" | "filled"

export type EditViewerStatus =
  | { state: "idle" }
  | { state: "detecting"; message?: string }
  | { state: "filling"; message?: string }
  | { state: "error"; message: string }

export type EditViewerFieldTargetStatus =
  | { state: "resolved" }
  | { state: "missing" }
  | { state: "invalid"; reason: string }

export interface EditViewerOptions {
  fieldPanel?: boolean
  search?: boolean
  filters?: boolean
  preview?: boolean
  filledOutput?: boolean
}

export interface EditViewerField {
  key: string
  description?: string
  type: "text" | "checkbox"
  value?: string | boolean | null
  target: DocumentAnchor | null
  targetStatus: EditViewerFieldTargetStatus
  bbox?: BBox
  combing?: boolean
  maxLength?: number
}

export interface EditViewerResult {
  fields: EditViewerField[]
  editType?: "agent" | "template"
}

export interface EditViewerInputField {
  key?: string
  description?: string
  type?: "text" | "checkbox"
  value?: string | boolean | null
  target?: DocumentAnchor | null
  bbox?: BBox
  combing?: boolean
  maxLength?: number
  max_length?: number
}

export interface EditViewerInputResult {
  fields?: readonly EditViewerInputField[] | null
  editType?: "agent" | "template"
}

export interface EditViewerDocumentSource {
  buffer?: ArrayBuffer | null
  src?: string | null
  mimeType: string
  filename?: string
}

export interface EditViewerProps {
  result: EditViewerInputResult | null
  sourceDocument?: EditViewerDocumentSource | null
  filledDocument?: EditViewerDocumentSource | null
  mode?: EditViewerMode | null
  onModeChange?: (mode: EditViewerMode) => void
  selectedFieldKey?: string | null
  onSelectedFieldKeyChange?: (key: string | null) => void
  status?: EditViewerStatus
  className?: string
  options?: EditViewerOptions
}

import type {
  DocumentAnchor,
  PdfAreaAnchor,
} from "@/components/ui/document-anchor"
import {
  createSegmentedDocumentModel,
  type DocumentSegment,
  type SegmentAnchor,
  type SegmentedDocumentModel,
} from "@/components/ui/segmented-document-model"
import type { BBox } from "@/components/viewers/lib/edit-types"

import type {
  EditViewerDocumentSource,
  EditViewerField,
  EditViewerFieldTargetStatus,
  EditViewerInputField,
  EditViewerInputResult,
  EditViewerMode,
  EditViewerOptions,
  EditViewerResult,
  EditViewerStatus,
} from "./edit-viewer-types"

export type EditViewerFilter =
  | "all"
  | "filled"
  | "empty"
  | "text"
  | "checkbox"
  | "no_location"

export interface EditViewerModeInput {
  fields: readonly EditViewerField[]
  sourceDocument?: EditViewerDocumentSource | null
  filledDocument?: EditViewerDocumentSource | null
  options: Required<EditViewerOptions>
}

export type EditViewerDocumentTarget =
  | { kind: "error"; message: string }
  | { kind: "empty"; message: string }
  | { kind: "source"; document: EditViewerDocumentSource; showOverlay: false }
  | { kind: "preview"; document: EditViewerDocumentSource; showOverlay: true }
  | { kind: "filled"; document: EditViewerDocumentSource; showOverlay: false }

const DEFAULT_OPTIONS: Required<EditViewerOptions> = {
  fieldPanel: true,
  search: true,
  filters: true,
  preview: true,
  filledOutput: true,
}

const MODE_FALLBACK_ORDER: EditViewerMode[] = ["filled", "preview", "source"]

const MODE_DISPLAY_ORDER: EditViewerMode[] = ["source", "preview", "filled"]

export function resolveEditViewerOptions(
  options: EditViewerOptions | undefined
): Required<EditViewerOptions> {
  return { ...DEFAULT_OPTIONS, ...options }
}

export function normalizeEditViewerResult(
  result: EditViewerInputResult | null | undefined
): EditViewerResult {
  const fields = result?.fields ?? []
  return {
    fields: fields.map(normalizeEditViewerField),
    editType: result?.editType,
  }
}

function normalizeEditViewerField(
  field: EditViewerInputField,
  index: number
): EditViewerField {
  const key = field.key || `field_${index}`
  const location = normalizeEditViewerFieldLocation(field)
  return {
    key,
    description: field.description || key || `Field ${index + 1}`,
    type: field.type === "checkbox" ? "checkbox" : "text",
    value: normalizeFieldValue(field.value),
    target: location.target,
    targetStatus: location.targetStatus,
    bbox: location.bbox,
    combing: field.combing,
    maxLength: normalizeMaxLength(field),
  }
}

function normalizeEditViewerFieldLocation(field: EditViewerInputField): {
  bbox?: BBox
  target: DocumentAnchor | null
  targetStatus: EditViewerFieldTargetStatus
} {
  if (field.target !== undefined) {
    return {
      target: field.target,
      targetStatus: field.target ? { state: "resolved" } : { state: "missing" },
    }
  }

  if (!field.bbox) {
    return { target: null, targetStatus: { state: "missing" } }
  }

  const bbox = normalizeBBox(field.bbox)
  if (!bbox) {
    return {
      target: null,
      targetStatus: { state: "invalid", reason: "Invalid field bbox" },
    }
  }

  return {
    bbox,
    target: editFieldTargetFromBBox(bbox),
    targetStatus: { state: "resolved" },
  }
}

export function editFieldTargetFromBBox(
  bbox: BBox | null | undefined
): DocumentAnchor | null {
  if (!bbox) return null
  return {
    kind: "pdf-area",
    pageNumber: bbox.page,
    left: bbox.left * 100,
    top: bbox.top * 100,
    width: bbox.width * 100,
    height: bbox.height * 100,
  }
}

function normalizeFieldValue(value: string | boolean | null | undefined) {
  if (typeof value === "boolean") return value
  if (value === null || value === undefined) return null
  return String(value)
}

function normalizeMaxLength(field: EditViewerInputField) {
  if ("maxLength" in field && typeof field.maxLength === "number") {
    return field.maxLength
  }
  if ("max_length" in field && typeof field.max_length === "number") {
    return field.max_length
  }
  return undefined
}

function normalizeBBox(bbox: BBox): BBox | undefined {
  const page = Number(bbox.page)
  const left = Number(bbox.left)
  const top = Number(bbox.top)
  const width = Number(bbox.width)
  const height = Number(bbox.height)

  if (
    !Number.isFinite(page) ||
    !Number.isFinite(left) ||
    !Number.isFinite(top) ||
    !Number.isFinite(width) ||
    !Number.isFinite(height) ||
    page < 1 ||
    width <= 0 ||
    height <= 0
  ) {
    return undefined
  }

  const normalizedLeft = clamp01(left)
  const normalizedTop = clamp01(top)
  const normalizedWidth = Math.min(clamp01(width), 1 - normalizedLeft)
  const normalizedHeight = Math.min(clamp01(height), 1 - normalizedTop)

  if (normalizedWidth <= 0 || normalizedHeight <= 0) return undefined

  return {
    page: Math.round(page),
    left: normalizedLeft,
    top: normalizedTop,
    width: normalizedWidth,
    height: normalizedHeight,
  }
}

function clamp01(value: number) {
  if (!Number.isFinite(value)) return 0
  return Math.max(0, Math.min(1, value))
}

export function isEditFieldChecked(field: EditViewerField) {
  if (typeof field.value === "boolean") return field.value
  if (typeof field.value !== "string") return false
  const value = field.value.trim().toLowerCase()
  return (
    value === "true" || value === "checked" || value === "yes" || value === "1"
  )
}

export function isEditFieldFilled(field: EditViewerField) {
  if (field.type === "checkbox") return isEditFieldChecked(field)
  return Boolean(
    typeof field.value === "string"
      ? field.value.trim().length > 0
      : field.value !== null && field.value !== undefined
  )
}

export function displayEditFieldValue(field: EditViewerField): string {
  if (field.type === "checkbox") {
    return isEditFieldChecked(field) ? "Checked" : "Unchecked"
  }
  if (field.value === null || field.value === undefined) return ""
  return String(field.value).trim()
}

export function deriveEditViewerModes(input: EditViewerModeInput) {
  const hasPreviewTargets = input.fields.some((field) =>
    Boolean(getEditViewerPdfAreaAnchor(field))
  )
  const hasSource = Boolean(input.sourceDocument)
  const filledOutputAvailable = Boolean(input.filledDocument)
  const modes: EditViewerMode[] = []

  if (hasSource) {
    modes.push("source")
  }

  if (
    input.options.preview &&
    hasSource &&
    hasPreviewTargets &&
    input.sourceDocument &&
    canPreviewEditViewerDocument(input.sourceDocument)
  ) {
    modes.push("preview")
  }

  if (input.options.filledOutput && filledOutputAvailable) {
    modes.push("filled")
  }

  return sortModes(modes)
}

function sortModes(modes: EditViewerMode[]) {
  const rank = new Map(MODE_DISPLAY_ORDER.map((mode, index) => [mode, index]))
  return Array.from(new Set(modes)).sort(
    (a, b) => (rank.get(a) ?? 99) - (rank.get(b) ?? 99)
  )
}

export function resolveEditViewerMode({
  availableModes,
  requestedMode,
  currentMode,
}: {
  availableModes: readonly EditViewerMode[]
  requestedMode?: EditViewerMode | null
  currentMode?: EditViewerMode | null
}): EditViewerMode | null {
  if (requestedMode && availableModes.includes(requestedMode)) {
    return requestedMode
  }
  if (currentMode && availableModes.includes(currentMode)) {
    return currentMode
  }
  return (
    MODE_FALLBACK_ORDER.find((mode) => availableModes.includes(mode)) ?? null
  )
}

export function filterEditViewerFields({
  fields,
  query,
  filter,
}: {
  fields: readonly EditViewerField[]
  query?: string
  filter?: EditViewerFilter
}) {
  const normalizedQuery = (query ?? "").trim().toLowerCase()
  const resolvedFilter = filter ?? "all"

  return fields.filter((field) => {
    if (resolvedFilter === "filled" && !isEditFieldFilled(field)) return false
    if (resolvedFilter === "empty" && isEditFieldFilled(field)) return false
    if (resolvedFilter === "text" && field.type !== "text") return false
    if (resolvedFilter === "checkbox" && field.type !== "checkbox") {
      return false
    }
    if (resolvedFilter === "no_location" && field.target) return false
    if (!normalizedQuery) return true
    return (
      field.key.toLowerCase().includes(normalizedQuery) ||
      (field.description ?? "").toLowerCase().includes(normalizedQuery) ||
      displayEditFieldValue(field).toLowerCase().includes(normalizedQuery)
    )
  })
}

export interface EditViewerFieldGroup {
  key: string
  label: string
  page: number | null
  fields: EditViewerField[]
}

export type EditViewerFieldProjection = {
  fields: readonly EditViewerField[]
  fieldByKey: ReadonlyMap<string, EditViewerField>
  fieldsByPage: ReadonlyMap<number, readonly EditViewerField[]>
  locatedFields: readonly EditViewerField[]
  unlocatedFields: readonly EditViewerField[]
  visibleFields: readonly EditViewerField[]
  fieldGroups: readonly EditViewerFieldGroup[]
  fieldCount: number
  visibleFieldCount: number
  filledCount: number
}

export function createEditViewerFieldProjection({
  fields,
  query,
  filter,
}: {
  fields: readonly EditViewerField[]
  query: string
  filter: EditViewerFilter
}): EditViewerFieldProjection {
  const visibleFields = filterEditViewerFields({ fields, query, filter })
  return {
    fields,
    fieldByKey: createEditViewerFieldMap(fields),
    fieldsByPage: groupLocatedEditViewerFieldsByPage(fields),
    locatedFields: fields.filter((field) => Boolean(field.target)),
    unlocatedFields: fields.filter((field) => !field.target),
    visibleFields,
    fieldGroups: groupEditViewerFieldsByPage(visibleFields),
    fieldCount: fields.length,
    visibleFieldCount: visibleFields.length,
    filledCount: fields.filter(isEditFieldFilled).length,
  }
}

export function createEditViewerFieldMap(fields: readonly EditViewerField[]) {
  const fieldByKey = new Map<string, EditViewerField>()
  for (const field of fields) {
    if (!fieldByKey.has(field.key)) {
      fieldByKey.set(field.key, field)
    }
  }
  return fieldByKey
}

export function createEditViewerSegmentedDocumentModel(
  fields: readonly EditViewerField[]
): SegmentedDocumentModel {
  const segments: DocumentSegment[] = []
  const anchors: SegmentAnchor[] = []

  fields.forEach((field, index) => {
    const pdfAnchor = getEditViewerPdfAreaAnchor(field)
    const segment: DocumentSegment = {
      id: editViewerSegmentId(field.key, index),
      label: field.description || field.key,
      pages: pdfAnchor ? [pdfAnchor.pageNumber] : [],
      color: field.type === "checkbox" ? "var(--chart-2)" : "var(--chart-1)",
      index,
      sourceId: field.key,
    }

    if (pdfAnchor) {
      anchors.push(editViewerPdfAnchorToSegmentAnchor(pdfAnchor, segment.id))
    }

    segments.push(segment)
  })

  return createSegmentedDocumentModel({ anchors, segments })
}

function editViewerSegmentId(fieldKey: string, index: number) {
  return `edit:${fieldKey || "field"}:${index}`
}

function editViewerPdfAnchorToSegmentAnchor(
  anchor: PdfAreaAnchor,
  segmentId: string
): SegmentAnchor {
  return {
    id: `${segmentId}:anchor`,
    segmentId,
    pageNumber: anchor.pageNumber,
    bounds: {
      x: pdfPercentToUnit(anchor.left),
      y: pdfPercentToUnit(anchor.top),
      width: pdfPercentToUnit(anchor.width),
      height: pdfPercentToUnit(anchor.height),
    },
  }
}

function pdfPercentToUnit(value: number) {
  if (!Number.isFinite(value)) return 0
  return value > 1 ? value / 100 : value
}

export function groupEditViewerFieldsByPage(
  fields: readonly EditViewerField[]
): EditViewerFieldGroup[] {
  const pageGroups = groupLocatedEditViewerFieldsByPage(fields)
  const unlocatedFields: EditViewerField[] = []

  for (const field of fields) {
    if (!field.target) {
      unlocatedFields.push(field)
    }
  }

  const groups: EditViewerFieldGroup[] = Array.from(pageGroups.entries())
    .sort((a, b) => a[0] - b[0])
    .map(([page, pageFields]) => ({
      key: `page:${page}`,
      label: `Page ${page}`,
      page,
      fields: pageFields,
    }))

  if (unlocatedFields.length > 0) {
    groups.push({
      key: "no-location",
      label: "No location",
      page: null,
      fields: unlocatedFields,
    })
  }

  return groups
}

export function groupLocatedEditViewerFieldsByPage(
  fields: readonly EditViewerField[]
): Map<number, EditViewerField[]> {
  const pageGroups = new Map<number, EditViewerField[]>()

  for (const field of fields) {
    const anchor = getEditViewerPdfAreaAnchor(field)
    if (!anchor) continue
    const pageFields = pageGroups.get(anchor.pageNumber) ?? []
    pageFields.push(field)
    pageGroups.set(anchor.pageNumber, pageFields)
  }

  return pageGroups
}

export function getEditViewerPdfAreaAnchor(
  field: EditViewerField
): PdfAreaAnchor | null {
  return field.target?.kind === "pdf-area" ? field.target : null
}

export function resolveEditViewerDocumentTarget({
  filledDocument,
  mode,
  sourceDocument,
  status,
}: {
  filledDocument: EditViewerDocumentSource | null
  mode: EditViewerMode | null
  sourceDocument: EditViewerDocumentSource | null
  status: EditViewerStatus
}): EditViewerDocumentTarget {
  if (status.state === "error") {
    return { kind: "error", message: status.message }
  }

  if (mode === "filled" && filledDocument) {
    return { kind: "filled", document: filledDocument, showOverlay: false }
  }

  if (mode === "preview" && sourceDocument) {
    return { kind: "preview", document: sourceDocument, showOverlay: true }
  }

  if (mode === "source" && sourceDocument) {
    return { kind: "source", document: sourceDocument, showOverlay: false }
  }

  if (!mode) {
    return { kind: "empty", message: "No edit view is available." }
  }

  return { kind: "empty", message: "Document preview is unavailable." }
}

export function canPreviewEditViewerDocument(
  document: EditViewerDocumentSource
) {
  const filename = document.filename ?? ""
  return (
    document.mimeType.toLowerCase().includes("application/pdf") ||
    filename.toLowerCase().endsWith(".pdf")
  )
}

import type { EditViewerField } from "./edit-viewer-types"

export const EDIT_FIELD_ACCENTS: Record<
  EditViewerField["type"],
  { line: string; tint: string; text: string; badge: string }
> = {
  text: {
    line: "var(--color-chart-3)",
    tint: "color-mix(in oklab, var(--color-chart-3) 12%, transparent)",
    text: "var(--color-chart-4)",
    badge: "border-chart-3/30 bg-chart-3/10 text-chart-4 dark:text-chart-2",
  },
  checkbox: {
    line: "var(--color-amber-500)",
    tint: "color-mix(in oklab, var(--color-amber-500) 14%, transparent)",
    text: "var(--color-amber-600)",
    badge: "border-warning/30 bg-warning/10 text-warning-foreground",
  },
}

"use client"

import * as React from "react"

import type {
  PageOverlayProps,
  PdfViewerHandle,
} from "@/components/ui/pdf-viewer"

import type {
  EditViewerDocumentTarget,
  EditViewerFieldGroup,
  EditViewerFilter,
} from "./edit-viewer-model"
import type {
  EditViewerDocumentSource,
  EditViewerField,
  EditViewerMode,
  EditViewerOptions,
  EditViewerResult,
  EditViewerStatus,
} from "./edit-viewer-types"

export type EditViewerProviderState = {
  status: EditViewerStatus
  result: EditViewerResult
  fields: readonly EditViewerField[]
  filledCount: number
  hasOutput: boolean
  fieldByKey: ReadonlyMap<string, EditViewerField>
  fieldsByPage: ReadonlyMap<number, readonly EditViewerField[]>
}

export type EditViewerModeState = {
  mode: EditViewerMode | null
  modes: readonly EditViewerMode[]
  setMode: (mode: EditViewerMode) => void
}

export type EditViewerFieldsState = {
  fields: readonly EditViewerField[]
  visibleFields: readonly EditViewerField[]
  fieldGroups: readonly EditViewerFieldGroup[]
  locatedFields: readonly EditViewerField[]
  unlocatedFields: readonly EditViewerField[]
  filledCount: number
  fieldCount: number
  visibleFieldCount: number
  query: string
  setQuery: (query: string) => void
  filter: EditViewerFilter
  setFilter: (filter: EditViewerFilter) => void
  canSearch: boolean
  canFilter: boolean
}

export type EditViewerSelectionState = {
  selectedFieldKey: string | null
  activeFieldKey: string | null
  selectField: (fieldKey: string) => void
  clearFieldSelection: () => void
  previewField: (fieldKey: string | null) => void
}

export type EditViewerDocumentState = {
  target: EditViewerDocumentTarget
  mode: EditViewerMode | null
  sourceDocument: EditViewerDocumentSource | null
  filledDocument: EditViewerDocumentSource | null
  viewerRef: React.RefObject<PdfViewerHandle | null>
  renderPageOverlay: (props: PageOverlayProps) => React.ReactNode
}

export type EditStore = {
  state: EditViewerProviderState
  mode: EditViewerModeState
  fields: EditViewerFieldsState
  selection: EditViewerSelectionState
  document: EditViewerDocumentState
  options: Required<EditViewerOptions>
}

const EditStoreContext = React.createContext<EditStore | null>(null)

export function EditStoreProvider({
  children,
  value,
}: {
  children: React.ReactNode
  value: EditStore
}) {
  return (
    <EditStoreContext.Provider value={value}>
      {children}
    </EditStoreContext.Provider>
  )
}

export function useEditStore(): EditStore {
  const store = React.useContext(EditStoreContext)
  if (!store) {
    throw new Error("EditViewer parts must be used within EditViewerProvider.")
  }
  return store
}

"use client"

import * as React from "react"

import type {
  PageOverlayProps,
  PdfViewerHandle,
} from "@/components/ui/pdf-viewer"
import { SegmentedDocumentProvider } from "@/components/ui/segmented-document-provider"
import { useSegmentedItemLink } from "@/components/ui/segmented-item-link"

import {
  createEditViewerFieldProjection,
  createEditViewerSegmentedDocumentModel,
  deriveEditViewerModes,
  normalizeEditViewerResult,
  resolveEditViewerDocumentTarget,
  resolveEditViewerMode,
  resolveEditViewerOptions,
  type EditViewerDocumentTarget,
  type EditViewerFieldGroup,
  type EditViewerFieldProjection,
  type EditViewerFilter,
} from "./edit-viewer-model"
import { EditFieldOverlayLayer } from "./edit-viewer-overlays"
import {
  EditStoreProvider,
  type EditStore,
  type EditViewerDocumentState,
  type EditViewerFieldsState,
  type EditViewerModeState,
  type EditViewerProviderState,
  type EditViewerSelectionState,
} from "./edit-viewer-store"
import type {
  EditViewerDocumentSource,
  EditViewerField,
  EditViewerMode,
  EditViewerOptions,
  EditViewerProps,
  EditViewerResult,
  EditViewerStatus,
} from "./edit-viewer-types"

export type EditViewerProviderProps = Omit<EditViewerProps, "className"> & {
  children: React.ReactNode
}

export function EditViewerProvider({
  result,
  sourceDocument = null,
  filledDocument = null,
  mode,
  onModeChange,
  selectedFieldKey,
  onSelectedFieldKeyChange,
  status = { state: "idle" },
  options,
  children,
}: EditViewerProviderProps) {
  const viewerRef = React.useRef<PdfViewerHandle>(null)
  const resolvedOptions = React.useMemo(
    () => resolveEditViewerOptions(options),
    [options]
  )
  const editResult = React.useMemo(
    () => normalizeEditViewerResult(result),
    [result]
  )
  const [query, setQuery] = React.useState("")
  const [filter, setFilter] = React.useState<EditViewerFilter>("all")
  const fieldProjection = React.useMemo(
    () =>
      createEditViewerFieldProjection({
        fields: editResult.fields,
        query,
        filter,
      }),
    [editResult.fields, filter, query]
  )
  const modeState = useEditViewerModeState({
    fields: fieldProjection.fields,
    sourceDocument,
    filledDocument,
    options: resolvedOptions,
    mode,
    onModeChange,
  })
  const documentTarget = React.useMemo(
    () =>
      resolveEditViewerDocumentTarget({
        filledDocument,
        mode: modeState.mode,
        sourceDocument,
        status,
      }),
    [filledDocument, modeState.mode, sourceDocument, status]
  )
  const segmentedDocument = React.useMemo(
    () => createEditViewerSegmentedDocumentModel(fieldProjection.fields),
    [fieldProjection.fields]
  )

  return (
    <SegmentedDocumentProvider model={segmentedDocument}>
      <EditViewerResolvedProvider
        documentTarget={documentTarget}
        editResult={editResult}
        filledDocument={filledDocument}
        filter={filter}
        fieldProjection={fieldProjection}
        modeState={modeState}
        onSelectedFieldKeyChange={onSelectedFieldKeyChange}
        options={resolvedOptions}
        query={query}
        selectedFieldKey={selectedFieldKey}
        setFilter={setFilter}
        setQuery={setQuery}
        sourceDocument={sourceDocument}
        status={status}
        viewerRef={viewerRef}
      >
        {children}
      </EditViewerResolvedProvider>
    </SegmentedDocumentProvider>
  )
}

function useEditViewerModeState({
  fields,
  filledDocument,
  mode,
  onModeChange,
  options,
  sourceDocument,
}: {
  fields: readonly EditViewerField[]
  filledDocument: EditViewerDocumentSource | null
  mode?: EditViewerMode | null
  onModeChange?: EditViewerProps["onModeChange"]
  options: Required<EditViewerOptions>
  sourceDocument: EditViewerDocumentSource | null
}): EditViewerModeState {
  const modes = React.useMemo(
    () =>
      deriveEditViewerModes({
        fields,
        sourceDocument,
        filledDocument,
        options,
      }),
    [fields, filledDocument, options, sourceDocument]
  )
  const isModeControlled = mode !== undefined
  const [uncontrolledMode, setUncontrolledMode] =
    React.useState<EditViewerMode | null>(null)
  const resolvedMode = resolveEditViewerMode({
    availableModes: modes,
    requestedMode: mode,
    currentMode: isModeControlled ? null : uncontrolledMode,
  })

  React.useEffect(() => {
    if (isModeControlled || uncontrolledMode === resolvedMode) return
    setUncontrolledMode(resolvedMode)
  }, [isModeControlled, resolvedMode, uncontrolledMode])

  const setMode = React.useCallback(
    (nextMode: EditViewerMode) => {
      if (!modes.includes(nextMode)) return
      if (!isModeControlled) {
        setUncontrolledMode(nextMode)
      }
      onModeChange?.(nextMode)
    },
    [isModeControlled, modes, onModeChange]
  )

  return React.useMemo(
    () => ({
      mode: resolvedMode,
      modes,
      setMode,
    }),
    [modes, resolvedMode, setMode]
  )
}

function EditViewerResolvedProvider({
  children,
  documentTarget,
  editResult,
  filledDocument,
  filter,
  fieldProjection,
  modeState,
  onSelectedFieldKeyChange,
  options,
  query,
  selectedFieldKey,
  setFilter,
  setQuery,
  sourceDocument,
  status,
  viewerRef,
}: {
  children: React.ReactNode
  documentTarget: EditViewerDocumentTarget
  editResult: EditViewerResult
  fieldProjection: EditViewerFieldProjection
  filledDocument: EditViewerDocumentSource | null
  filter: EditViewerFilter
  modeState: EditViewerModeState
  onSelectedFieldKeyChange?: EditViewerProps["onSelectedFieldKeyChange"]
  options: Required<EditViewerOptions>
  query: string
  selectedFieldKey?: string | null
  setFilter: (filter: EditViewerFilter) => void
  setQuery: (query: string) => void
  sourceDocument: EditViewerDocumentSource | null
  status: EditViewerStatus
  viewerRef: React.RefObject<PdfViewerHandle | null>
}) {
  const {
    fieldByKey,
    fieldGroups,
    fields,
    fieldsByPage,
    filledCount,
    locatedFields,
    unlocatedFields,
    visibleFields,
  } = fieldProjection
  const selection = useEditViewerSelectionBridge({
    fieldByKey,
    onSelectedFieldKeyChange,
    selectedFieldKey,
  })
  const renderPageOverlay = useEditViewerPageOverlay({
    activeFieldKey: selection.activeFieldKey,
    fieldsByPage,
    mode: modeState.mode,
    previewField: selection.previewField,
    selectField: selection.selectField,
  })
  const state = React.useMemo<EditViewerProviderState>(
    () => ({
      status,
      result: editResult,
      fields,
      fieldByKey,
      fieldsByPage,
      filledCount,
      hasOutput:
        status.state === "error" ||
        modeState.modes.length > 0 ||
        fields.length > 0,
    }),
    [
      editResult,
      fieldByKey,
      fields,
      fieldsByPage,
      filledCount,
      modeState.modes.length,
      status,
    ]
  )
  const fieldsState = React.useMemo<EditViewerFieldsState>(
    () => ({
      fields,
      visibleFields,
      fieldGroups,
      locatedFields,
      unlocatedFields,
      filledCount,
      fieldCount: fieldProjection.fieldCount,
      visibleFieldCount: fieldProjection.visibleFieldCount,
      query,
      setQuery,
      filter,
      setFilter,
      canSearch: options.search,
      canFilter: options.filters,
    }),
    [
      fieldGroups,
      fieldProjection.fieldCount,
      fieldProjection.visibleFieldCount,
      fields,
      filledCount,
      filter,
      locatedFields,
      options.filters,
      options.search,
      query,
      setFilter,
      setQuery,
      unlocatedFields,
      visibleFields,
    ]
  )
  const selectionState = React.useMemo<EditViewerSelectionState>(
    () => selection,
    [selection]
  )
  const documentState = React.useMemo<EditViewerDocumentState>(
    () => ({
      target: documentTarget,
      mode: modeState.mode,
      sourceDocument,
      filledDocument,
      viewerRef,
      renderPageOverlay,
    }),
    [
      documentTarget,
      filledDocument,
      modeState.mode,
      renderPageOverlay,
      sourceDocument,
      viewerRef,
    ]
  )
  const value = React.useMemo<EditStore>(
    () => ({
      state,
      mode: modeState,
      fields: fieldsState,
      selection: selectionState,
      document: documentState,
      options,
    }),
    [documentState, fieldsState, modeState, options, selectionState, state]
  )

  return <EditStoreProvider value={value}>{children}</EditStoreProvider>
}

function useEditViewerSelectionBridge({
  fieldByKey,
  onSelectedFieldKeyChange,
  selectedFieldKey,
}: {
  fieldByKey: ReadonlyMap<string, EditViewerField>
  onSelectedFieldKeyChange?: EditViewerProps["onSelectedFieldKeyChange"]
  selectedFieldKey?: string | null
}): EditViewerSelectionState {
  const {
    activeItemId,
    navigateItem,
    previewItem,
    selectItem,
    selectedItemId,
  } = useSegmentedItemLink({ initialItemId: selectedFieldKey })

  React.useEffect(() => {
    if (selectedFieldKey === undefined) return
    if (selectedFieldKey && !fieldByKey.has(selectedFieldKey)) {
      selectItem(null)
      onSelectedFieldKeyChange?.(null)
      return
    }
    selectItem(selectedFieldKey ?? null)
  }, [fieldByKey, onSelectedFieldKeyChange, selectItem, selectedFieldKey])

  const selectField = React.useCallback(
    (fieldKey: string) => {
      if (!fieldByKey.has(fieldKey)) return
      selectItem(fieldKey)
      navigateItem(fieldKey, { behavior: "smooth" })
      onSelectedFieldKeyChange?.(fieldKey)
    },
    [fieldByKey, navigateItem, onSelectedFieldKeyChange, selectItem]
  )
  const clearFieldSelection = React.useCallback(() => {
    selectItem(null)
    onSelectedFieldKeyChange?.(null)
  }, [onSelectedFieldKeyChange, selectItem])
  const previewField = React.useCallback(
    (fieldKey: string | null) => {
      if (fieldKey && !fieldByKey.has(fieldKey)) return
      previewItem(fieldKey)
      if (fieldKey) {
        navigateItem(fieldKey, { behavior: "auto", clearPreview: false })
      }
    },
    [fieldByKey, navigateItem, previewItem]
  )

  return React.useMemo(
    () => ({
      selectedFieldKey: selectedItemId,
      activeFieldKey: activeItemId,
      selectField,
      clearFieldSelection,
      previewField,
    }),
    [
      activeItemId,
      clearFieldSelection,
      previewField,
      selectField,
      selectedItemId,
    ]
  )
}

function useEditViewerPageOverlay({
  activeFieldKey,
  fieldsByPage,
  mode,
  previewField,
  selectField,
}: {
  activeFieldKey: string | null
  fieldsByPage: ReadonlyMap<number, readonly EditViewerField[]>
  mode: EditViewerMode | null
  previewField: (fieldKey: string | null) => void
  selectField: (fieldKey: string) => void
}) {
  return React.useCallback(
    ({ pageNumber }: PageOverlayProps) => (
      <EditFieldOverlayLayer
        fieldsByPage={fieldsByPage}
        pageNumber={pageNumber}
        mode={mode}
        effectiveFieldKey={activeFieldKey}
        onFieldHover={previewField}
        onFieldSelect={selectField}
      />
    ),
    [activeFieldKey, fieldsByPage, mode, previewField, selectField]
  )
}

