    >
      <div className="flex h-10 flex-shrink-0 items-center gap-2 border-b px-3">
        <h2 className="px-1 text-sm font-medium">Form fields</h2>
        <span className="ml-auto pr-1 text-xs text-muted-foreground tabular-nums">
          <span className="text-success-foreground">{filledCount}</span>
          {" / "}
          {fieldCount} filled
        </span>
      </div>

      {(showSearch || showFilters) && (
        <div className="flex flex-shrink-0 flex-col gap-2 border-b px-3 py-2.5">
          {showSearch ? (
            <label className="relative block">
              <span className="sr-only">Search form fields</span>
              <Search className="pointer-events-none absolute top-1/2 left-2.5 size-3.5 -translate-y-1/2 text-muted-foreground" />
              <input
                value={query}
                onChange={(event) => onQueryChange(event.target.value)}
                placeholder="Search key, description, value..."
                className="h-7 w-full rounded-md border bg-transparent pr-2 pl-8 text-xs outline-none placeholder:text-muted-foreground/70 focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/20"
              />
            </label>
          ) : null}

          {showFilters ? (
            <div className="flex flex-wrap items-center gap-1">
              {EDIT_VIEWER_FILTER_OPTIONS.map(({ value, label }) => (
                <button
                  key={value}
                  type="button"
                  onClick={() => onFilterChange(value)}
                  aria-pressed={filter === value}
                  className={cn(
                    "rounded px-2 py-0.5 text-[11px] font-medium transition-colors",
                    filter === value
                      ? "bg-muted text-foreground"
                      : "text-muted-foreground hover:bg-muted/60"
                  )}
                >
                  {label}
                </button>
              ))}
            </div>
          ) : null}
        </div>
      )}

      <ScrollArea className="min-h-0 flex-1">
        {visibleFieldCount === 0 ? (
          <p className="px-4 py-6 text-center text-xs text-muted-foreground">
            No fields match.
          </p>
        ) : (
          fieldGroups.map((fieldGroup) => (
            <div key={fieldGroup.key}>
              <div className="sticky top-0 z-10 flex items-center justify-between border-b bg-background/95 px-4 py-1 text-[10px] font-medium tracking-wide text-muted-foreground uppercase backdrop-blur">
                <span>{fieldGroup.label}</span>
                <span className="tabular-nums">{fieldGroup.fields.length}</span>
              </div>
              {fieldGroup.fields.map((field) => (
                <EditViewerFieldRow
                  key={field.key}
                  field={field}
                  active={field.key === effectiveFieldKey}
                  selected={field.key === selectedFieldKey}
                  onFieldHover={onFieldHover}
                  onFieldSelect={onFieldSelect}
                />
              ))}
            </div>
          ))
        )}
      </ScrollArea>
    </div>
  )
}

const EDIT_VIEWER_FILTER_OPTIONS: Array<{
  value: EditViewerFilter
  label: string
}> = [
  { value: "all", label: "All" },
  { value: "filled", label: "Filled" },
  { value: "empty", label: "Empty" },
  { value: "text", label: "Text" },
  { value: "checkbox", label: "Checkbox" },
  { value: "no_location", label: "No location" },
]

function EditViewerFieldRow({
  field,
  active,
  selected,
  onFieldHover,
  onFieldSelect,
}: {
  field: EditViewerField
  active: boolean
  selected: boolean
  onFieldHover: (key: string | null) => void
  onFieldSelect: (key: string) => void
}) {
  const accent = EDIT_FIELD_ACCENTS[field.type]
  const filled = isEditFieldFilled(field)
  const value = displayEditFieldValue(field)

  return (
    <button
      type="button"
      onMouseEnter={() => onFieldHover(field.key)}
      onMouseLeave={() => onFieldHover(null)}
      onFocus={() => onFieldHover(field.key)}
      onBlur={() => onFieldHover(null)}
      onClick={() => onFieldSelect(field.key)}
      aria-current={selected ? "true" : undefined}
      className={cn(
        "flex w-full flex-col items-start gap-1 border-b border-border/60 px-4 py-2.5 text-left transition-colors focus-visible:ring-[3px] focus-visible:ring-ring/20 focus-visible:outline-none",
        active ? "bg-muted" : "hover:bg-muted/50"
      )}
    >
      <div className="flex w-full items-center gap-2">
        <span
          className={cn(
            "h-3 w-0.5 flex-shrink-0 rounded-full transition-opacity",
            selected ? "opacity-100" : "opacity-0"
          )}
          style={{ backgroundColor: accent.line }}
        />
        <span className="truncate font-mono text-[11px] text-foreground">
          {field.key}
        </span>
        <span
          className={cn(
            "ml-auto flex-shrink-0 rounded border px-1.5 py-0 text-[9px] font-medium tracking-wide uppercase",
            accent.badge
          )}
        >
          {field.type}
        </span>
      </div>
      {field.description ? (
        <span className="line-clamp-1 text-[11px] text-muted-foreground">
          {field.description}
        </span>
      ) : null}
      <span
        className={cn(
          "w-full truncate font-mono text-[11px]",
          filled ? "text-success-foreground" : "text-muted-foreground/50 italic"
        )}
      >
        {filled ? value : "- empty -"}
      </span>
    </button>
  )
}

"use client"

import * as React from "react"

import type { BlobViewerSource, UrlViewerSource } from "@/lib/viewer-source"
import { FileViewer } from "@/components/ui/file-viewer"
import {
  PdfViewer,
  type PageOverlayProps,
  type PdfViewerHandle,
} from "@/components/ui/pdf-viewer"
import { useSegmentedDocumentViewport } from "@/components/ui/segmented-document-provider"

import {
  canPreviewEditViewerDocument,
  type EditViewerDocumentTarget,
} from "./edit-viewer-model"
import { EditViewerErrorState, NoDocumentState } from "./edit-viewer-states"
import type { EditViewerDocumentSource } from "./edit-viewer-types"

export function EditViewerDocumentPane({
  target,
  renderPageOverlay,
  viewerRef,
}: {
  target: EditViewerDocumentTarget
  renderPageOverlay: (props: PageOverlayProps) => React.ReactNode
  viewerRef: React.RefObject<PdfViewerHandle | null>
}) {
  if (target.kind === "error") {
    return <EditViewerErrorState message={target.message} />
  }

  if (target.kind === "filled") {
    return <FilledDocumentRenderer document={target.document} />
  }

  if (target.kind === "source" || target.kind === "preview") {
    return (
      <SourceDocumentRenderer
        document={target.document}
        renderPageOverlay={renderPageOverlay}
        viewerRef={viewerRef}
        showPreview={target.showOverlay}
      />
    )
  }

  return <NoDocumentState message={target.message} />
}

function SourceDocumentRenderer({
  document,
  renderPageOverlay,
  viewerRef,
  showPreview,
}: {
  document: EditViewerDocumentSource
  renderPageOverlay: (props: PageOverlayProps) => React.ReactNode
  viewerRef: React.RefObject<PdfViewerHandle | null>
  showPreview: boolean
}) {
  const { documentHandlers } = useSegmentedDocumentViewport()
  const source = useDocumentViewerSource(document)
  const setPdfViewerHandle = React.useCallback(
    (handle: PdfViewerHandle | null) => {
      viewerRef.current = handle
      documentHandlers.setDocumentHandle(handle)
    },
    [documentHandlers, viewerRef]
  )

  React.useEffect(
    () => () => documentHandlers.setDocumentHandle(null),
    [documentHandlers]
  )

  if (!source) {
    return <NoDocumentState message="Document preview is unavailable." />
  }

  if (canPreviewEditViewerDocument(document)) {
    return (
      <PdfViewer
        ref={setPdfViewerHandle}
        source={source}
        bare
        className="h-full"
        onScrollProgressChange={documentHandlers.onScrollProgressChange}
        onVisiblePageChange={documentHandlers.onCurrentPageChange}
        renderPageOverlay={showPreview ? renderPageOverlay : undefined}
      />
    )
  }

  if (showPreview) {
    return <NoDocumentState message="Preview requires a PDF source document." />
  }

  return <FileViewer source={source} bare className="h-full" />
}

function FilledDocumentRenderer({
  document,
}: {
  document: EditViewerDocumentSource
}) {
  const source = useDocumentViewerSource(document)
  if (!source) {
    return <NoDocumentState message="Document preview is unavailable." />
  }

  return <FileViewer source={source} bare className="h-full" />
}

function useDocumentViewerSource(
  document: EditViewerDocumentSource
): UrlViewerSource | BlobViewerSource | null {
  return React.useMemo(() => {
    const fileName = document.filename ?? "document"
    if (document.src) {
      return {
        kind: "url",
        url: document.src,
        fileName,
        mimeType: document.mimeType,
      }
    }
    if (!document.buffer) return null

    return {
      kind: "blob",
      blob: new Blob([document.buffer], { type: document.mimeType }),
      identityKey: editViewerBufferIdentityKey(document.buffer),
      fileName,
      mimeType: document.mimeType,
    }
  }, [document.buffer, document.filename, document.mimeType, document.src])
}

const editViewerBufferKeys = new WeakMap<ArrayBuffer, string>()
let nextEditViewerBufferKey = 0

function editViewerBufferIdentityKey(buffer: ArrayBuffer): string {
  let key = editViewerBufferKeys.get(buffer)
  if (!key) {
    nextEditViewerBufferKey += 1
    key = `edit-viewer-buffer:${nextEditViewerBufferKey}`
    editViewerBufferKeys.set(buffer, key)
  }
  return key
}

